// The Claude Code arm's prose parser (src/bench/claudeprose.ts): `/code-review`
// answers in markdown, never through the harness's findings tool, so its
// findings are read back out of the text. The golden set is twelve real
// outputs of the arm (tests/fixtures/claude-prose/<id>.md, with the PR's
// changed files beside each as <id>.files.txt); every expectation below was
// written by hand from reading that fixture — not generated by the parser.

import { describe, expect, it } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  findLocations,
  leadInSaysFindings,
  normalisePath,
  parseClaudeProse,
  resolvePath,
} from "../src/bench/claudeprose.js";

const FX = join(resolve(dirname(fileURLToPath(import.meta.url))), "fixtures", "claude-prose");

function fixture(id: string): { text: string; files: string[] | null } {
  const f = join(FX, `${id}.files.txt`);
  return {
    text: readFileSync(join(FX, `${id}.md`), "utf8"),
    files: existsSync(f) ? readFileSync(f, "utf8").split("\n").filter(Boolean) : null,
  };
}

interface Want {
  path: string;
  start: number;
  end?: number;
  /** The finding's text starts with this (markdown kept)… */
  starts: string;
  /** …and contains each of these (its body, its nested bullets). */
  has?: string[];
  /** …and not these (text that belongs to the next block). */
  lacks?: string[];
  written?: string;
}

interface Golden {
  id: string;
  shape: string;
  want: Want[];
  skipped?: { non_finding?: number; recap?: number; unlocated?: number };
}

