describe("the prose parser, on real /code-review outputs (golden fixtures)", () => {
  for (const g of GOLDEN) {
    it(`${g.id}: ${g.shape}`, () => {
      const { text, files } = fixture(g.id);
      expect(files, "every fixture carries its PR's changed files").not.toBeNull();
      const r = parseClaudeProse(text, files);
      expect(r.findings.map((f) => `${f.path}:${f.start_line}-${f.end_line}`)).toEqual(
        g.want.map((w) => `${w.path}:${w.start}-${w.end ?? w.start}`),
      );
      g.want.forEach((w, i) => {
        const f = r.findings[i]!;
        expect(f.text.startsWith(w.starts), `${f.text.slice(0, 120)}`).toBe(true);
        for (const h of w.has ?? []) expect(f.text).toContain(h);
        for (const l of w.lacks ?? []) expect(f.text).not.toContain(l);
        expect(f.written).toBe(w.written ?? w.path);
        expect(f.matched).toBe(true);
      });
      if (g.skipped)
        expect(r.skipped).toEqual({ non_finding: 0, recap: 0, unlocated: 0, ...g.skipped });
    });
  }

  it("the golden set is what the directory holds", () => {
    for (const g of GOLDEN) expect(existsSync(join(FX, `${g.id}.md`)), g.id).toBe(true);
    expect(GOLDEN.length).toBe(12);
  });

  it("without a changed-file list the paths stay as written (normalised), unchecked", () => {
    const { text } = fixture("gofr-dev__gofr@dc0b3e6");
    const r = parseClaudeProse(text, null);
    expect(r.findings.map((f) => [f.path, f.matched])).toEqual(
      Array.from({ length: 5 }, () => ["mongo.go", null]),
    );
    const ts = parseClaudeProse(fixture("microsoft__typescript-go@b970689").text);
    expect(ts.findings.map((f) => f.path)).toEqual([
      "internal/parser/reparser.go",
      "internal/ast/utilities.go",
    ]);
  });
});

describe("the parser's rules, one at a time", () => {
  const paths = (s: string, files?: string[]) =>
    parseClaudeProse(s, files).findings.map((f) => `${f.path}:${f.start_line}-${f.end_line}`);

  it("a lead-in that counts issues wins over 'no bugs' in the same sentence", () => {
    const s =
      "I found no runtime bugs in this diff, only two low-severity issues:\n" +
      "- lib/public/Security/ICrypto.php:16 — the example calls a method that does not exist.\n" +
      "- lib/public/L10N/ILanguageIterator.php:40 — `next()` is now typed `void`.\n\n" +
      "The other changes checked out:\n- `Util.php` uses `IConfig` without importing it, but it resolves.\n";
    expect(paths(s)).toEqual([
      "lib/public/Security/ICrypto.php:16-16",
      "lib/public/L10N/ILanguageIterator.php:40-40",
    ]);
  });

  it("an opener that counts bugs keeps its list even when its last sentence says the rest looks fine", () => {
    const s =
      "I found 2 likely bugs, all in `rag/x.py`. The changes in `graphrag/utils.py` look correct to me.\n\n" +
      "- **rag/x.py:575** — the single-name case is never deleted.\n- **rag/x.py:78** — filters now match text.\n";
    expect(paths(s)).toEqual(["rag/x.py:575-575", "rag/x.py:78-78"]);
  });

  it("a 'Findings:' heading after a 'What I checked:' list", () => {
    const s =
      "I found no correctness bugs in this range. The two findings are both debug logging.\n\n" +
      "**What I checked:**\n- **Batching:** still writes every key (`src/a.ts:12`).\n\n" +
      "**Findings:**\n- `src/core/state.ts:79` — seven `[PERF]` log lines ship.\n- `src/core/state.ts:626` — a fixed claim is logged.\n";
    const r = parseClaudeProse(s);
    expect(r.findings.map((f) => f.start_line)).toEqual([79, 626]);
    expect(r.skipped.non_finding).toBe(1);
  });

  it("only the item's FIRST line locates it; a location in its body alone is not enough", () => {
    const s =
      "I found one bug.\n\n- **Wrong order** — the caller sorts after filtering.\n  See `src/a.ts:40` for the call.\n";
    const r = parseClaudeProse(s);
    expect(r.findings).toEqual([]);
    expect(r.skipped.unlocated).toBe(1);
  });

  it("the first location of the first line is the item's; later ones are body text", () => {
    const s =
      "I found 1 issue.\n\n- `src/a.ts:198` (and line 229; same bug in `src/b.ts:12`) — a clipboard error stalls.\n";
    expect(paths(s)).toEqual(["src/a.ts:198-198"]);
  });

  it("ranges, extensionless files and a column", () => {
    expect(
      paths(
        "I found 3 bugs.\n\n- `src/a.ts:12-34` — x\n- **`src/Makefile:519`** — y\n- src/b.go:7:3 — z\n",
      ),
    ).toEqual(["src/a.ts:12-34", "src/Makefile:519-519", "src/b.go:7-7"]);
    expect(findLocations("see `x/y.ts:30–28`")[0]).toMatchObject({ start: 28, end: 30 });
  });

  it("things that look like locations and are not", () => {
    expect(
      findLocations("at 10:00, v1.2:3, https://example.com:443/x, host:8080, ratio 3:1"),
    ).toEqual([]);
  });

  it("a paragraph finding does not take a list that has locations of its own", () => {
    const s = "`src/a.ts:5` — the first bug.\n- `src/b.ts:9` — a second one.\n";
    expect(paths(s)).toEqual(["src/a.ts:5-5", "src/b.ts:9-9"]);
  });

  it("a recap list is dropped only when EVERY located item repeats a finding", () => {
    const s =
      "I found 2 bugs.\n\n1. `src/a.ts:5` — one.\n2. `src/a.ts:9` — two.\n\n" +
      "Summary:\n- `src/a.ts:5` — one.\n- `src/c.ts:1` — a third, only here.\n";
    expect(paths(s)).toEqual(["src/a.ts:5-5", "src/a.ts:9-9", "src/a.ts:5-5", "src/c.ts:1-1"]);
  });

  it("lead-ins, one by one", () => {
    const no = [
      "What I checked:",
      "Two behaviours I looked at and chose not to report:",
      "Two behaviour changes are worth knowing about, though neither is a clear bug:",
      "I also checked a few other things that turned out fine:",
      "These looked correct to me:",
      "To fix it:",
      "Two leftovers are not bugs, so I didn't report them:",
    ];
    for (const l of no) expect(leadInSaysFindings(l, null), l).toBe(false);
    const yes = [
      "I found 4 likely bugs in this diff.",
      "I reported one minor text issue:",
      "Findings:",
      "I found no runtime bugs in this diff, only two low-severity issues:",
      "The review found 2 real bugs, both from the same mistake.",
    ];
    for (const l of yes) expect(leadInSaysFindings(l, null), l).toBe(true);
    // a neutral lead-in inherits the review's opening
    expect(
      leadInSaysFindings("The diff touches three files:", "I found no bugs in this diff."),
    ).toBe(false);
    expect(leadInSaysFindings("The diff touches three files:", "I found two problems.")).toBe(true);
    expect(leadInSaysFindings(null, null)).toBe(true);
  });
});

describe("path resolution against the PR's changed files", () => {
  const files = ["src/a.ts", "web/index.ts", "server/index.ts", "pkg/mongo/mongo.go"];

  it("normalises the sandbox prefix and ./", () => {
    expect(normalisePath("/work/repo/o__r/src/a.ts")).toBe("src/a.ts");
    expect(normalisePath("./src/a.ts")).toBe("src/a.ts");
  });

  it("exact, git a/ b/ prefixes, a unique suffix either way", () => {
    expect(resolvePath("src/a.ts", files)).toEqual({ path: "src/a.ts", matched: true });
    expect(resolvePath("b/src/a.ts", files)).toEqual({ path: "src/a.ts", matched: true });
    expect(resolvePath("mongo.go", files)).toEqual({ path: "pkg/mongo/mongo.go", matched: true });
    expect(resolvePath("/tmp/x/src/a.ts", files)).toEqual({ path: "src/a.ts", matched: true });
  });

  it("an ambiguous or absent match keeps the path as written, unmatched", () => {
    expect(resolvePath("index.ts", files)).toEqual({ path: "index.ts", matched: false });
    expect(resolvePath("src/other.ts", files)).toEqual({ path: "src/other.ts", matched: false });
    expect(resolvePath("src/other.ts", null)).toEqual({ path: "src/other.ts", matched: null });
  });
});
